"""Rebuild provenance and a readable validation report. No download bundle."""
import json,html,hashlib
from pathlib import Path
from datetime import datetime,timezone
root=Path(__file__).resolve().parents[1];r=json.loads((root/'data/validation.json').read_text());e=json.loads((root/'data/eop.json').read_text());a=json.loads((root/'data/error-investigation.json').read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
p={'model':r['model'],'scope':r['scope'],'domain':r['domain'],'ephemeris':{'name':'DE441','url':'https://naif.jpl.nasa.gov/pub/naif/generic_kernels/spk/planets/de441_part-2.bsp','sha256':sha(root/'data/de441-solar.bsp')},'legacy_eop':{k:v for k,v in e['legacy'].items() if k!='rows'},'jpl_eop2':{k:v for k,v in e['jpl'].items() if k!='rows'},'iers':{k:e[k] for k in ['source','url','retrieved','sha256']},'erfa':{'source':'https://github.com/THRASTRO/sofa.js','sha256':sha(root/'vendor/erfa.min.js'),'license':'vendor/LICENSE-ERFA-JS.txt'},'runtime_privacy':'Local arithmetic, no geolocation, storage, coordinate upload or calculation API','validation':{'horizons':r['horizons']['cases'],'native_modern':r['native'],'native_legacy':r['native_legacy'],'spk_boundaries':r['spk_boundaries'],'boundaries':r['boundaries']},'remaining':'Public legacy file is November17, reference usesNovember18. Exact archived reference input has not been obtained. Microsecond historical residuals are not a claim of bitwise equivalence or physical accuracy.'}
(root/'data/provenance.json').write_text(json.dumps(p,ensure_ascii=False,indent=2))
names={'historical_all':'历史：UTC < 2026-11-01，全部纬度','historical_polar':'历史：|纬度| > 85°','recent_all':'近期及未来：UTC ≥ 2026-11-01','all':'全体：包括不同版本预测与外推','nonpolar':'全日期：|纬度| ≤ 85°','polar':'全日期：|纬度| > 85°','observed_nonpolar':'观测数据区：|纬度| ≤ 85°','predicted_nonpolar':'预测数据区：|纬度| ≤ 85°','extrapolated_nonpolar':'末值外推：|纬度| ≤ 85°','holdout':'随机保留地点：全日期'}
rows=''
for k,label in names.items():
 s=r['horizons'][k];rows+='<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [label,s['count'],f"{s['max_abs_ms']/1000:.9f}",f"{s['p95_ms']/1000:.9f}",f"{s['p99_ms']/1000:.9f}",f"{s['rms_ms']/1000:.9f}"])+'</tr>'
h=r['horizons']['historical_all'];worst=r['horizons']['all']['worst'];when=datetime.fromtimestamp(worst['ms']/1000,timezone.utc).isoformat()
body=f'''<a href="index.html">返回计算器</a><h1>原始格式数据、插值修正与完整对照</h1><p class="lead">42,200组 Horizons 对照 · 两套各113,524组原生库校验 · 52,596组星历边界校验</p>
+<div class="notice"><strong>历史对照已收敛到微秒级；精确的11月18日归档仍未取得。</strong><p>已从官方公开目录获取原始格式 EOP，并通过 Chrome、HTTPS 和匿名FTP交叉核对。当前镜像是2026-11-17版，对照结果标注 eop.261118.p270214（2026-11-18版）。不会把不同版本标成同一文件。</p><p>历史 {h['count']:,} 个样本（包括纬度±89.999999°）最大差异 <strong>{h['max_abs_ms']*1000:.3f} 微秒</strong>。近期预测和远期外推使用不同版本，近极区仍可放大到秒或分钟；全体样本最大差异 {r['horizons']['all']['max_abs_ms']/1000:.3f} 秒。有限采样不是全域精度证明。</p></div>
+<h2>这次实际修正了什么</h2><ol><li>使用真正的JPL原始格式文件：ITRF93 / ICRF93、UTC时间轴、dPsi/dEps。此前EOP2对应ITRF2008、TAI时间轴和dX/dY，两者不能混用。</li><li>对齐IAU1976岁差、IAU1980章动以及含章动修正的格林尼治视恒星时。没有用经验时间偏移消除残差。</li><li>识别并实现相邻两组七点、六次Lagrange多项式的线性拼接。历史近极区的最大差异由普通四点插值的约2.065秒降到约1.42微秒。</li></ol>
+<h2>插值方法的依据与独立验证</h2><pre>F(x) = (1 − t) Pᵢ(x) + t Pᵢ₊₁(x)\nt = (x − xᵢ) / (xᵢ₊₁ − xᵢ)</pre><p>每个P使用七个相邻原始数据点；两组共享六个点，合计八个局部节点。此构造在节点保持函数及一阶导数连续，精确再现六次及以下多项式。采用UTC节点，TAI−UTC使用闰秒阶跃表，不能平滑插值。</p><p>七点阶数来自63个专用诊断输出的行为识别；不是声称拿到了JPL程序源码。随后用未参与识别的42,200个分层案例验证。JPL文档中Newhall的低阶构造提供数学依据，但没有将其误称为Horizons七点阶数的官方公开说明。另有77项插值性质检查。</p>
+<h2>覆盖范围</h2><p>Horizons：40地点×1,055时刻。覆盖全球等面积、赤道、±180°、南北85°/89°/89.99°/89.999999°、高度−1000至100000米和12个随机保留地点。日期包括1973–2027逐月、1972及2028–2099扩展点、全部数据内闰秒邻域和固定种子随机时刻。</p><p>独立原生库：现代模型和原始格式模型各113,524案例，均含每日20,044点、星历分段邻域58,440点、随机32,768点、角点224点、人工参数压力2,048点。原始格式模型与原生ERFA+jplephem的最大差异为 {r['native_legacy']['max_abs_ms']*1000:.6f} 微秒；这是实现一致性验证，不是物理准确性认证。</p><p>另有52,596个原始SPK记录边界及前后1微秒位置/速度对照、91项输入/边界检查和25个闰秒事件。切换模型时章动输入标签会在dPsi/dEps与dX/dY之间切换，并取消旧模型的手动参数。</p>
+<h2>完整差异分布</h2><p>以下单位全部为<strong>秒</strong>，P95/P99是绝对差异分位数。预测区的统计包含11月17日与18日两版数据的差异，不能当作同版算法误差。</p><div class="scroll"><table><thead><tr><th>分组</th><th>样本</th><th>最大绝对差</th><th>P95</th><th>P99</th><th>RMS</th></tr></thead><tbody>{rows}</tbody></table></div>
+<p>全体最差样本：UTC {when}，经度{worst['longitude']}°、纬度{worst['latitude']}°、椭球高{worst['height']}m。该例位于近极区且为远期固定末值外推。</p>
+<h2>剩余限制</h2><p>本次取得的是官方真实原始格式文件，但不是参考输出使用的11月18日那份精确归档。官方镜像的缓存重新验证、Chrome下载和匿名FTP读取均得到同一11月17日文件；公开目录未列出目标归档。不能认定目标文件不存在，也不能以旧文件冒充它。近期预测的极移和UT1差异会在近极点被强烈放大。</p><p>历史约1.42微秒的残差还包含参考输出舍入、时间尺度与数值实现差异，尚未逐项分解到最后一位。极点附近物理位置与极移测量本身也有不确定度；算法一致不等于绝对真实太阳时同样准确。</p>
+<h2>定义域与复现</h2><p>经度[-180°,180°]、纬度(-90°,90°)、椭球高[-1000,100000]m。东九区1972-01-01 09:15至2099-12-31 23:59:59.999；自动模式受所选文件覆盖范围约束，外推默认关闭。角秒允许小数且须小于60；时间控件不接受23:59:60，但闰秒前后跳变已验证。</p><pre>node tests/full-domain.cjs\nnode tests/legacy-tests.cjs\nnode tests/spk-boundaries.cjs\npython3 scripts/report.py</pre><p>测试重放不调用API，源码保留原生参考生成器、独立探针、历史基线及全部对照统计。</p>
+<p><a href="data/eop-2026-11-17.long">已取得的原始文件（2026-11-17）</a> · <a href="data/validation.json">完整统计</a> · <a href="data/provenance.json">来源与哈希</a> · <a href="data/error-investigation.json">调查记录</a> · <a href="https://ssd.jpl.nasa.gov/ftp/ssd/">官方原始文件目录</a> · <a href="https://ssd.jpl.nasa.gov/horizons/manual.html">Horizons定义</a> · <a href="https://descanso.jpl.nasa.gov/monograph/series2/Descanso2_S02.pdf">Newhall低阶插值依据</a></p>'''.replace('\n+','\n')
